                            <div dangerouslySetInnerHTML={{ __html: data.conclusion }} />
                        </div>

                        {/* CTA Button */}
                        <footer className="mt-12 pt-8 border-t border-gray-200 flex justify-center">
                            <div className="not-prose" dangerouslySetInnerHTML={{ __html: data.cta_html }} />
